#include <stdio.h>

/* classificarImc le o peso (kg, inteiro) e a altura (cm, inteiro) digitados,
   calcula o IMC e imprime a faixa numa linha so.
   A leitura e a conta do IMC ja estao escritas.
   Falta a cascata de quatro degraus, do mais ALTO para o mais baixo:
     obesidade      -> imc de 30.0 para cima
     sobrepeso      -> imc de 25.0 a 30.0   (faixa fechada, com &&)
     normal         -> imc de 18.5 a 25.0   (faixa fechada, com &&)
     abaixo do peso -> o resto (o else) */
void classificarImc(void) {
    int peso = 0;
    int altura = 0;

    scanf("%d %d", &peso, &altura);

    double metros = (double)altura / 100;
    double imc = peso / (metros * metros);

    /* escreva a cascata aqui, no lugar desta linha */
    printf("faixa\n");
}

