#include <stdio.h>

void classificarImc(void) {
    int peso = 0;
    int altura = 0;

    scanf("%d %d", &peso, &altura);

    double metros = (double)altura / 100;
    double imc = peso / (metros * metros);

    if (imc >= 30.0) {
        printf("obesidade\n");
    } else if (imc >= 25.0 && imc < 30.0) {
        printf("sobrepeso\n");
    } else if (imc >= 18.5 && imc < 25.0) {
        printf("normal\n");
    } else {
        printf("abaixo do peso\n");
    }
}
